from math import gcd

def lcm(a, b):
    return a * b // gcd(a, b)

k = list(map(int, input().split()))
k1, k2, k3 = k

L = lcm(lcm(k1, k2), k3)

found = False
for o1 in range(k1):
    for o2 in range(k2):
        for o3 in range(k3):
            ok = all((t % k1 == o1) or (t % k2 == o2) or (t % k3 == o3) for t in range(L))
            if ok:
                found = True
                break
        if found: break
    if found: break

print("YES" if found else "NO")
